parameters.functionCode:
const connection = $('Check Connection').first().json;
const slowQueries = $('Slow Query Log').all();
const tableSizes = $('Table Sizes').all();
const indexIssues = $('Index Usage Check').all();

const issues = [];

if (slowQueries.length > 5) {
  issues.push(`⚠️ ${slowQueries.length} slow queries in last hour`);
}

const largeTables = tableSizes.filter(t => t.json.data_mb > 1000);
if (largeTables.length > 0) {
  issues.push(`⚠️ ${largeTables.length} tables exceed 1GB`);
}

if (indexIssues.length > 5) {
  issues.push(`⚠️ ${indexIssues.length} low-cardinality indexes detected`);
}

return [{
  json: {
    status: issues.length > 0 ? 'WARNING' : 'HEALTHY',
    mysql_version: connection.mysql_version,
    uptime_hours: Math.round(connection.uptime_seconds / 3600),
    slow_query_count: slowQueries.length,
    large_tables: largeTables.length,
    index_issues: indexIssues.length,
    issues: issues,
    has_issues: issues.length > 0,
    timestamp: new Date().toISOString()
  }
}];

